_EXACT = {}
for row in T:
    _EXACT[row[0]] = dict(zip(LANG_ORDER, row[1:]))
_PATTERNS = [(re.compile("^" + p + "$", re.S), tpl, groups) for p, tpl, groups in PATTERNS]
SEPARATORS = ("   ·   ", "  ·  ")
_cache = {}


def tr(s, lang):
    if lang == "es" or not s:
        return s
    key = (s, lang)
    if key in _cache:
        return _cache[key]
    out = None
    row = _EXACT.get(s)
    if row:
        out = row.get(lang)
    if out is None:
        for p, tpl, groups in _PATTERNS:
            m = p.match(s)
            if not m:
                continue
            template = tpl.get(lang) or tpl.get("*") or tpl.get("en")
            values = {}
            for i in range(1, (p.groups or 0) + 1):
                v = m.group(i) or ""
                if i in groups:
                    v = tr(v, lang)
                elif "list" in groups:
                    v = (" / ").join(tr(x.strip().capitalize(), lang) for x in v.split(" y "))
                values[str(i)] = v
            out = re.sub(r"\{(\d)\}", lambda mm: values.get(mm.group(1), ""), template)
            break
    if out is None:
        for sep in SEPARATORS:
            if sep in s:
                out = sep.join(tr(part, lang) for part in s.split(sep))
                break
    if out is None:
        out = s
    if len(_cache) < 8000:
        _cache[key] = out
    return out
